jsxGraph.script:
board.suspendUpdate();
board.create('arrow', [[-1.2,0],[3.5,0]], {strokeColor:'black'});
board.create('arrow', [[0,-3],[0,18]], {strokeColor:'black'});
var f=function(x){ return 8*Math.pow(x, 3) - 3*Math.pow(x, 4); };
board.create('functiongraph', [f, -0.9, 3.1], {strokeColor:'#1d4ed8',strokeWidth:2});
board.create('point', [0, 0], {name:'(0,0)', size:2, color:'red', label:{offset:[10,-10]}});
board.create('point', [8/3, 0], {name:'(8/3,0)', size:2, color:'red', label:{offset:[10,10]}});
board.create('point', [2, 16], {name:'Max(2, 16)', size:2, color:'purple', label:{offset:[-40,15]}});
board.create('point', [4/3, 256/27], {name:'POI(4/3, 256/27)', size:2, color:'green', label:{offset:[10,-15]}});
board.create('text', [3.3, -1.2, 'x'], {fontSize:13});
board.create('text', [0.2, 17, 'y'], {fontSize:13});
board.unsuspendUpdate();
